 private static final String PREFS="ev_charge_calculator",KEY_LANGUAGE="app_language"; private static final int WATCH_TAG=0x4C414E47; private static final String[] LANGS={"en","es","fr","de","it","pt"}; private static final Map<String,String[]> TR=new HashMap<>();
 private LanguageManager(){}
 public static String getSelectedLanguage(Context c){String s=c.getSharedPreferences(PREFS,0).getString(KEY_LANGUAGE,null);if(s==null){s=getSystemLanguage();c.getSharedPreferences(PREFS,0).edit().putString(KEY_LANGUAGE,s).apply();}return isSupported(s)?s:"en";}
 public static String getEffectiveLanguage(Context c){return getSelectedLanguage(c);}
 public static void setLanguage(Context c,String l){String s=isSupported(l)?l:"en";c.getSharedPreferences(PREFS,0).edit().putString(KEY_LANGUAGE,s).apply();apply(c,s);}
 public static void applyStored(Context c){apply(c,getSelectedLanguage(c));}
 public static void apply(Context c,String l){String s=isSupported(l)?l:"en";Locale locale=Locale.forLanguageTag(s);Locale.setDefault(locale);Configuration cfg=new Configuration(c.getResources().getConfiguration());cfg.setLocale(locale);c.getResources().updateConfiguration(cfg,c.getResources().getDisplayMetrics());}
 private static String getSystemLanguage(){String s=Locale.getDefault().getLanguage();return isSupported(s)?s:"en";}
 public static boolean isSupported(String l){if(l==null)return false;for(String s:LANGS)if(s.equals(l))return true;return false;}
 public static String displayName(String l){if("en".equals(l))return "🇬🇧  English";if("es".equals(l))return "🇪🇸  Español";if("fr".equals(l))return "🇫🇷  Français";if("de".equals(l))return "🇩🇪  Deutsch";if("it".equals(l))return "🇮🇹  Italiano";if("pt".equals(l))return "🇵🇹  Português";return l;}
 public static void showSelector(Activity a){String[] c=LANGS, names={displayName("en"),displayName("es"),displayName("fr"),displayName("de"),displayName("it"),displayName("pt")};int checked=-1;String cur=getSelectedLanguage(a);for(int i=0;i<c.length;i++)if(c[i].equals(cur))checked=i;new android.app.AlertDialog.Builder(a).setTitle(t(a,"Idioma")).setSingleChoiceItems(names,checked,(d,w)->{setLanguage(a,c[w]);d.dismiss();a.recreate();}).show();}
