 private static void add(String es,String en,String fr,String de,String it,String pt){TR.put(es,new String[]{es,en,fr,de,it,pt});}
 public static String t(Context c,String key){return t(key,getEffectiveLanguage(c));}
 public static String t(String key,String lang){if(key==null)return null;String[] a=TR.get(key);if(a==null)return key;if("es".equals(lang))return a[0];if("fr".equals(lang))return a[2];if("de".equals(lang))return a[3];if("it".equals(lang))return a[4];if("pt".equals(lang))return a[5];return a[1];}
 public static String translateDynamic(Context c,String s){if(s==null)return null;String lang=getEffectiveLanguage(c);if("es".equals(lang))return s;for(Map.Entry<String,String[]> e:TR.entrySet()){String[] a=e.getValue();for(String x:a)if(x.equals(s))return t(e.getKey(),lang);}return s;}
 public static void translateViews(Activity a){translateView(a,a.findViewById(android.R.id.content));}
 private static void translateView(Context c,View v){if(v instanceof TextView){TextView tv=(TextView)v;CharSequence cs=tv.getText();if(cs!=null){String s=cs.toString(),n=translateDynamic(c,s);if(!s.equals(n))tv.setText(n);}}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)translateView(c,g.getChildAt(i));}}
